BEGIN READ ONLY; SELECT c."Slug",a."Id" AS asset_id,a."Status" AS asset_status,m."Status" AS maintenance_status,m."CompletedOn",m."CompanyId"=a."CompanyId" AS maintenance_scoped,m."CompletionNotes" FROM "AssetMaintenances" m JOIN "Assets" a ON a."Id"=m."AssetId" JOIN "Companies" c ON c."Id"=a."CompanyId" WHERE a."AssetTag"='SANTA-KABUL-20261025-01'; SELECT ev."EventType",ev."CompanyId"=a."CompanyId" AS event_scoped FROM "AssetEvents" ev JOIN "Assets" a ON a."Id"=ev."AssetId" WHERE a."AssetTag"='SANTA-KABUL-20261025-01' ORDER BY ev."OccurredAt"; COMMIT;
